import clone from 'rfdc';
import { REDUCER_ACTION_TYPE } from '../../constant';
import { deleteDesignValueByIdInChildren, findDesignValueById } from '../../utils';
/**
 * reducer
 * @description 对设计值进行修改
 */
var reducer = function (state, action) {
  switch (action.type) {
    // 修改FormItem的props
    case REDUCER_ACTION_TYPE.updateFormItemProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.formItemProps = action.payload.props;
        }
        return clone()(state);
      }
    // 修改控件本身的props
    case REDUCER_ACTION_TYPE.updateFieldProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.fieldProps = action.payload.props;
        }
        return clone()(state);
      }
    // 修改控件样式的props
    case REDUCER_ACTION_TYPE.updateStyleProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.styleProps = action.payload.props;
        }
        return clone()(state);
      }
    // 修改控件Actions的props
    case REDUCER_ACTION_TYPE.updateActionsProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.actionsProps = action.payload.props;
        }
        return clone()(state);
      }
    // 修改控件Flex的props
    case REDUCER_ACTION_TYPE.updateFlexProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.flexProps = action.payload.props;
        }
        return clone()(state);
      }
    // 修改控件children
    case REDUCER_ACTION_TYPE.updateChildrenProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.children = action.payload.props;
        }
        return clone()(state);
      }
    // 在children中增加一个元素
    case REDUCER_ACTION_TYPE.addChildrenById:
      {
        if (!state) return state;
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          if (!designValue.props.children) {
            designValue.props.children = [];
          }
          designValue.props.children.push(action.payload.child);
        }
        return clone()(state);
      }
    // 删除指定id的children
    case REDUCER_ACTION_TYPE.deleteChildrenById:
      {
        if (!state) return state;
        deleteDesignValueByIdInChildren(action.payload.id, state);
        return clone()(state);
      }
    case REDUCER_ACTION_TYPE.updateDataSourceConfig:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.dataSourceConfig = action.payload.dataSourceConfig;
        }
        return clone()(state);
      }
    // 什么都不做
    default:
      return state;
  }
};
export default reducer;